#include <memory>
struct Body;                              // hidden body (pimpl)
std::unique_ptr<Body> make_body();        // returns ownership
void use(const Body&);                    // borrows
int main() {
    auto owner = make_body();             // move-only: no copy, no leak on throw
    std::shared_ptr<Body> shared = std::move(owner);
    std::weak_ptr<Body> watch = shared;   // non-owning back edge
    if (auto locked = watch.lock()) use(*locked);
}   // deleter runs at the last owner

