template <class Body> class Handle {           // More C++ Idioms: handle/body
  public:
    explicit Handle(Body *b) : body_(b) {}
    ~Handle() { delete body_; }
    Body *operator->() const { return body_; }
    Body &operator*() const { return *body_; }
  private:
    Body *body_;
    Handle(const Handle&);             // rule of three: no copy without a
    Handle &operator=(const Handle&);  // documented ownership-transfer policy
};

